def prepare_geometries(module_name="tools.glm_perf.reconstruction_native"):
    import importlib

    native = importlib.import_module(module_name)
    DECODE_ROWS, GLM_GEOMETRIES, ProjectionGeometry = (
        native.DECODE_ROWS,
        native.GLM_GEOMETRIES,
        native.ProjectionGeometry,
    )

    shapes = ((128, 256), (256, 512), *GLM_GEOMETRIES)
    return tuple(
        ProjectionGeometry(rows, experts, n, k) for experts in (3, 72) for n, k in shapes for rows in DECODE_ROWS
    )

def prepare():
    import importlib, hashlib, sys
    from pathlib import Path
    import torch
    for name in ('_C_ascend::npu_w2_swiglu_310', '_C_ascend::npu_w2_route_combine_310'):
        torch._C._dispatch_find_schema_or_throw(name, '')
    import importlib.util
    package = 'glm_reconstruction_v9_helpers'
    package_root = Path('/home/matteius/experiments/glm-reconstruction-20261006/build-native-allbits-v9/glm_reconstruction_v9_helpers')
    if package not in sys.modules:
        spec = importlib.util.spec_from_file_location(package, package_root/'__init__.py', submodule_search_locations=[str(package_root)])
        module = importlib.util.module_from_spec(spec)
        sys.modules[package] = module
        spec.loader.exec_module(module)
    if Path(sys.modules[package].__file__).resolve() != (package_root/'__init__.py').resolve():
        raise ValueError('native helper package already belongs to another build')
    helpers = {'glm_reconstruction_v9_helpers.glm_int4': '45a0eca35044364286376a4d52b6fa95c5653241b8446a3d60a2f1a66008e1de', 'glm_reconstruction_v9_helpers.reconstruction_native': '9bf814f721c063009c3e211841a55f7940c849c99d018d0822227f1cc3f5752c', 'glm_reconstruction_v9_helpers.reconstruction_probe': '0079e864d5dc6a924d5334811bd3133f8d2defb088c0601638ae5395c46f5dc7', 'glm_reconstruction_v9_helpers.expert_reconstruction': 'd9667fe04ae1e3396ccd7bebbd227204a5bebf593777a75a95b2a899cdda1662'}
    for name, expected in helpers.items():
        module = importlib.import_module(name)
        if hashlib.sha256(Path(module.__file__).read_bytes()).hexdigest() != expected:
            raise ValueError('worker helper differs from manifest: ' + name)
    from glm_reconstruction_v9_helpers.glm_int4 import NativeW4Projection
    root = Path('/home/matteius/experiments/glm-reconstruction-20261006/build-native-allbits-v9')
    geometries = prepare_geometries('glm_reconstruction_v9_helpers.reconstruction_native')
    resources = {'w4a8': NativeW4Projection(root/'glm_w4a8_pack.bin', root/'glm_w4a8_matmul.bin', geometries, namespace='glm_reconstruction_v9', tile_pipeline=True, output_columns=128, all_bits=True)}
    resources['int4a8'] = resources['w4a8']
    return resources

def validate(resources):
    from glm_reconstruction_v9_helpers.reconstruction_probe import component_cases, gate_case, graph_gate
    weight_bits = (2, 3, 4)
    records = [gate_case(resources['w4a8'], geometry, repeats=2, bits=bits) for bits in weight_bits for geometry in component_cases()]
    for bits in weight_bits:
        graph_gate(resources['w4a8'], component_cases()[2], bits)
    from glm_reconstruction_v9_helpers.reconstruction_probe import moe_pipeline_gate
    for bits in weight_bits:
        moe_pipeline_gate(resources['w4a8'], bits)
    return {'passed': True, 'cases': len(records), 'weight_format': 'unchanged_signed_block32', 'activation_format': 'new_group32_int8', 'model_quality': 'not_evaluated'}
